export async function mapSeries(items, worker) {
  const results = [];
  for (let i = 0; i < items.length; i++) {
    try {
      const result = await worker(items[i], i);
      results.push(result);
    } catch (error) {
      return Promise.reject(error);
    }
  }
  return results;
}
